head.script:
/**
 * @method
 * @name scwin.onpageload
 * @description 페이지 로드 시 사용자 ID를 설정하고, 프로젝트 목록을 조회한다.
 * @memberOf scwin
 * @date 2025.07.06
 * @example
 * scwin.onpageload();
 */
scwin.onpageload = function () {
    var usrId = $p.getComponentById("mf_pg_header").getWindow().scwin.USER_ID;
    var isAdmin = $p.getComponentById("mf_pg_header").getWindow().scwin.IS_ADMIN;
    // isAdmin 의 값 0 또는 1에 따라서 btn_newPjt 를 보여주거나 감추기
    if (isAdmin === 1 || isAdmin === "1") {
        // 관리자인 경우 새 프로젝트 생성 버튼 표시
        btn_newPjt.show();
    } else {
        // 일반 사용자인 경우 새 프로젝트 생성 버튼 숨김
        btn_newPjt.hide();
    }

    dmp_pjtVo.set("userId", usrId);    
    $c.sbm.execute(sbm_selectPjtVoList);
};

/**
 * @method
 * @name scwin.sbm_pjtList_submitdone
 * @description 프로젝트 리스트 조회 submission 완료 후 결과를 처리한다.
 * @param {Object} e - submission 이벤트 객체
 * @memberOf scwin
 * @date 2025.07.06
 */
scwin.sbm_pjtList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefined" || elHeader.resSuc === false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    dmp_pjtVoDetail.setEmptyValue();
    spn_listCnt.setLabel(elData.totalCount);
    dlt_pjtVoList.setJSON(elData.pjtVoList);

    scwin.setProgressRate();
    scwin.setProgressStyle();

    var totalPageCount = Math.ceil(elData.totalCount / dmp_pjtVo.get("pageSize"));
    pgl_pjtList.setCount(totalPageCount);
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(dmp_pjtVo.get("pageIndex"));
    pgl_pjtList.setSelectedIndex(dmp_pjtVo.get("pageIndex"));

    let num = Number(dmp_pjtVo.get("pageIndex"));
    num = (num - 1) * 10;
    grd_list.setStartRowNumber(num);
};

/**
 * @method
 * @name scwin.pgl_pjtList_onclick
 * @description 페이지네이션 클릭 시 페이지 인덱스를 설정하고 목록을 다시 조회한다.
 * @param {Number} idx - 선택된 페이지 인덱스
 * @memberOf scwin
 * @date 2025.07.06
 * @example
 * <w2:paging onClick="scwin.pgl_pjtList_onclick"/>
 */
scwin.pgl_pjtList_onclick = function (idx) {
    dmp_pjtVo.set("pageIndex", idx);
    $c.sbm.execute(sbm_selectPjtVoList);
};

/**
 * @method
 * @name scwin.setProgressRate
 * @description 각 프로젝트의 시작일과 종료일 기준으로 진행률을 계산하여 pjtProgress 컬럼에 설정한다.
 * @memberOf scwin
 * @date 2025.07.06
 */
scwin.setProgressRate = function () {
    const list = dlt_pjtVoList.getAllJSON();

    list.forEach(row => {
        const st = new Date(row.pjtSt);
        const et = new Date(row.pjtEt);
        const now = new Date();
        let percent = 0;

        if (!isNaN(st) && !isNaN(et) && st < et) {
            const total = et - st;
            const passed = Math.min(Math.max(now - st, 0), total);
            percent = Math.floor((passed / total) * 100);
        }

        row.pjtProgress = percent;
    });

    dlt_pjtVoList.setJSON(list);
};

/**
 * @method
 * @name scwin.setProgressStyle
 * @description 진행률 컬럼(pjtProgress)에 동적으로 배경 스타일 및 정렬 등을 적용한다.
 * @memberOf scwin
 * @date 2025.07.06
 */
scwin.setProgressStyle = function () {
    const rowCount = dlt_pjtVoList.getRowCount();
    const colIndex = grd_list.getColumnIndex("pjtProgress");

    for (let i = 0; i < rowCount; i++) {
        const percent = parseInt(dlt_pjtVoList.getCellData(i, "pjtProgress"), 10) || 0;

        let styleValue = "#ffffff";
        if (percent > 0) {
            styleValue = `linear-gradient(to right,
                #efdbde 0%,
                #EC9192 ${percent}%,
                #ffffff ${percent}%,
                #ffffff 100%)`;
        }

        const styles = [
            { type: "cell", rowIndex: i, colIndex, styleName: "background", styleValue },
            { type: "cell", rowIndex: i, colIndex, styleName: "border-radius", styleValue: "10px" },
            { type: "cell", rowIndex: i, colIndex, styleName: "text-align", styleValue: "center" },
            { type: "cell", rowIndex: i, colIndex, styleName: "color", styleValue: "#ffffff" }
        ];

        styles.forEach(style => grd_list.setStyleAll(style));
    }
};

/**
 * @method
 * @name scwin.statusFmt
 * @description pjtStatus 컬럼에 <span> 태그로 상태를 감싸서 반환 (CSS class 기반 스타일 적용)
 * @param {String} data - 셀의 실제 값 (ex. "진행중", "완료")
 * @param {String} formattedData - 포맷된 값 (사용하지 않음)
 * @param {Number} rowIndex - 행 인덱스
 * @param {Number} colIndex - 열 인덱스
 * @returns {String} HTML 문자열
 * @memberOf scwin
 * @date 2025.07.07
 */
scwin.statusFmt = function (data, formattedData, rowIndex, colIndex) {
    if (!data) return "";

    const statusClass = data.trim();
    return `<span class="status-tag ${statusClass}">${statusClass}</span>`;
};

scwin.btn_newPjt_onclick = function (e) {
    if ($p.getComponentById("mf_tab_content")) {
        var tabContent = $p.getComponentById("mf_tab_content").getScopeWindow().scwin;
        tabContent.openTab("pjt/Pjt.xml", "새 프로젝트");
    } else {
        alert("새 프로젝트 생성 페이지를 열 수 없습니다.");
    }
};
